#include <zephyr/kernel.h>
#include <zephyr/drivers/can.h>
#include <zephyr/ztest.h>

#define CAN_NODE DT_ALIAS(can0)

static const struct device *can_dev;

static void test_can_setup(void)
{
	can_dev = DEVICE_DT_GET(CAN_NODE);
	zassert_true(device_is_ready(can_dev), "CAN device not ready");
}

static void test_can_teardown(void)
{
	/* Reset CAN controller to a known state (stopped) after each test */
	int ret = can_stop(can_dev);
	zassert_equal(ret, 0, "can_stop failed in teardown");
}

ZTEST(can_driver_api, test_bitrate_limits)
{
	const struct can_capabilities *cap = can_get_capabilities(can_dev);
	zassert_not_null(cap, "Failed to get CAN capabilities");

	/* Test setting various valid bitrates */
	const uint32_t test_bitrates[] = {10000, 125000, 500000, 1000000};

	for (size_t i = 0; i < ARRAY_SIZE(test_bitrates); i++) {
		if (test_bitrates[i] < cap->max_bitrate && test_bitrates[i] > cap->min_bitrate) {
			int ret = can_set_bitrate(can_dev, test_bitrates[i]);
			zassert_equal(ret, 0, "Failed to set valid bitrate %d", test_bitrates[i]);
		}
	}

	/* Test setting invalid bitrates (too low/high) */
	int ret = can_set_bitrate(can_dev, cap->min_bitrate - 1);
	zassert_not_equal(ret, 0, "Set bitrate below min_bitrate");

	ret = can_set_bitrate(can_dev, cap->max_bitrate + 1);
	zassert_not_equal(ret, 0, "Set bitrate above max_bitrate");
}

ZTEST(can_driver_api, test_classic_get_capabilities)
{
	const struct can_capabilities *cap = can_get_capabilities(can_dev);

	zassert_not_null(cap, "Failed to get CAN capabilities");
	zassert_true(cap->max_bitrate > 0, "Max bitrate not set");
	zassert_true(cap->min_bitrate > 0, "Min bitrate not set");
	zassert_true(cap->max_bitrate >= cap->min_bitrate, "Max bitrate less than min bitrate");
	zassert_true(cap->sample_point_min > 0, "Sample point min not set");
	zassert_true(cap->sample_point_max > 0, "Sample point max not set");
	zassert_true(cap->sample_point_max >= cap->sample_point_min, "Max sample point less than min");
	zassert_true(cap->tseg1_min > 0, "TSEG1 min not set");
	zassert_true(cap->tseg1_max > 0, "TSEG1 max not set");
	zassert_true(cap->tseg1_max >= cap->tseg1_min, "Max TSEG1 less than min");
	zassert_true(cap->tseg2_min > 0, "TSEG2 min not set");
	zassert_true(cap->tseg2_max > 0, "TSEG2 max not set");
	zassert_true(cap->tseg2_max >= cap->tseg2_min, "Max TSEG2 less than min");
	zassert_true(cap->sjw_max > 0, "SJW max not set");
	zassert_true(cap->sjw_max >= cap->sjw_min, "Max SJW less than min");
	zassert_true(cap->prop_seg_max >= cap->prop_seg_min, "Max prop_seg less than min");

	/* Check supported modes */
	zassert_true(cap->supported_modes & CAN_MODE_NORMAL, "Normal mode not supported");
	zassert_true(cap->supported_modes & CAN_MODE_LOOPBACK, "Loopback mode not supported");
	zassert_true(cap->supported_modes & CAN_MODE_LISTENONLY, "Listen-only mode not supported");

	/* Check supported features */
	zassert_true(cap->supported_features & CAN_TX_TIMESTAMP, "TX timestamp not supported");
	zassert_true(cap->supported_features & CAN_RX_TIMESTAMP, "RX timestamp not supported");
}

ZTEST(can_driver_api, test_filters_added_while_stopped)
{
	struct can_filter filter = {
		.id = 0x123,
		.mask = 0x7FF,
		.flags = CAN_FILTER_DATA | CAN_FILTER_STD_ID,
	};

	int filter_id = can_add_rx_filter(can_dev, NULL, &filter);
	zassert_true(filter_id >= 0, "Failed to add filter while stopped");

	int ret = can_remove_rx_filter(can_dev, filter_id);
	zassert_equal(ret, 0, "Failed to remove filter");
}

ZTEST(can_driver_api, test_filters_preserved_through_bitrate_change)
{
	struct can_filter filter = {
		.id = 0x123,
		.mask = 0x7FF,
		.flags = CAN_FILTER_DATA | CAN_FILTER_STD_ID,
	};

	int filter_id = can_add_rx_filter(can_dev, NULL, &filter);
	zassert_true(filter_id >= 0, "Failed to add filter");

	int ret = can_set_bitrate(can_dev, 250000);
	zassert_equal(ret, 0, "Failed to change bitrate");

	/* Filters should be preserved, try to remove it */
	ret = can_remove_rx_filter(can_dev, filter_id);
	zassert_equal(ret, 0, "Filter not preserved after bitrate change");
}

ZTEST(can_driver_api, test_filters_preserved_through_mode_change)
{
	struct can_filter filter = {
		.id = 0x123,
		.mask = 0x7FF,
		.flags = CAN_FILTER_DATA | CAN_FILTER_STD_ID,
	};

	int filter_id = can_add_rx_filter(can_dev, NULL, &filter);
	zassert_true(filter_id >= 0, "Failed to add filter");

	int ret = can_set_mode(can_dev, CAN_MODE_LOOPBACK);
	zassert_equal(ret, 0, "Failed to change mode");

	/* Filters should be preserved, try to remove it */
	ret = can_remove_rx_filter(can_dev, filter_id);
	zassert_equal(ret, 0, "Filter not preserved after mode change");
}

ZTEST(can_driver_api, test_get_core_clock)
{
	uint32_t clock = can_get_core_clock(can_dev);
	zassert_true(clock > 0, "CAN core clock not set");
}

ZTEST(can_driver_api, test_get_state)
{
	enum can_state state;
	struct can_bus_err_cnt err_cnt;
	int ret;

	/* Ensure the device is stopped initially for a predictable state */
	ret = can_stop(can_dev);
	zassert_equal(ret, 0, "can_stop failed");

	ret = can_get_state(can_dev, &state, &err_cnt);
	zassert_equal(ret, 0, "can_get_state failed with %d", ret);

	zassert_equal(state, CAN_STATE_STOPPED, "Initial state not STOPPED");
	zassert_equal(err_cnt.tx_err_cnt, 0, "Initial TX error count not 0");
	zassert_equal(err_cnt.rx_err_cnt, 0, "Initial RX error count not 0");

	/* Start the CAN controller and check state */
	ret = can_start(can_dev);
	zassert_equal(ret, 0, "can_start failed");

	ret = can_get_state(can_dev, &state, &err_cnt);
	zassert_equal(ret, 0, "can_get_state failed after start with %d", ret);

	zassert_equal(state, CAN_STATE_ERROR_ACTIVE, "State not ERROR_ACTIVE after start");

	/* Stop the CAN controller and check state again */
	ret = can_stop(can_dev);
	zassert_equal(ret, 0, "can_stop failed");

	ret = can_get_state(can_dev, &state, &err_cnt);
	zassert_equal(ret, 0, "can_get_state failed after stop with %d", ret);

	zassert_equal(state, CAN_STATE_STOPPED, "State not STOPPED after stop");
}

ZTEST_SUITE(can_driver_api, NULL, test_can_setup, NULL, test_can_teardown, NULL);
